// The pictures the research pages carry.
//
// AN ENTRY ARGUING ABOUT A LOOK AND SHOWING NONE OF IT IS ASKING TO BE TAKEN ON
// TRUST. These are generated by the same harness, from the same scene, through
// the same real compositor as every number beside them, so a figure cannot
// drift from the code any more than a table can, which is the only reason to
// generate them rather than screenshot them once and forget.
//
// Full frames rather than crops: what these figures are for is composition and
// colour, and the palette argument in particular is about what happens to a
// whole picture. They are box-downsampled by two on the way out, which costs
// the print style's screen some of its bite and is the one honest compromise
// here.

import { defaultControls, type StyleControls, type StyleDefinition } from '../../src/core/style/style.ts';
import { COMIC_STYLE } from '../../src/core/style/comic/comic-style-pipeline.ts';
import { POSTER_STYLE } from '../../src/core/style/poster/poster-style-pipeline.ts';
import { PRINT_STYLE } from '../../src/core/style/print/print-style-pipeline.ts';
import { loadScene, StyleStage } from './harness.ts';
import { halve, tile, toBase64 } from './sheet.ts';

export interface Figure {
  readonly name: string;
  readonly width: number;
  readonly height: number;
  readonly columns: number;
  /** What each tile is, in the order they are laid out. */
  readonly tiles: readonly string[];
  /** Base64 of tightly packed 8-bit RGB. */
  readonly rgb: string;
}

const SIZE = { width: 1280, height: 720 };

interface Shot {
  readonly label: string;
  readonly style: StyleDefinition;
  readonly controls: Record<string, number>;
}

const SHEETS: readonly { name: string; columns: number; shots: readonly Shot[] }[] = [
  {
    name: 'styles',
    columns: 2,
    shots: [
      // Strength zero is a true no-op: the style's own fade takes the mix to
      // zero and the composite returns the source byte for byte. The untouched
      // frame therefore comes through the same path as the styled ones rather
      // than being pasted in beside them.
      { label: 'the photograph', style: COMIC_STYLE, controls: { strength: 0 } },
      { label: 'comic', style: COMIC_STYLE, controls: {} },
      { label: 'poster', style: POSTER_STYLE, controls: {} },
      { label: 'print', style: PRINT_STYLE, controls: {} },
    ],
  },
  {
    name: 'palettes',
    columns: 3,
    shots: [
      { label: 'the picture’s own colour', style: POSTER_STYLE, controls: { palette: 0 } },
      { label: 'Mural', style: POSTER_STYLE, controls: { palette: 1 } },
      { label: 'Riso', style: POSTER_STYLE, controls: { palette: 2 } },
    ],
  },
];

export async function figures(device: GPUDevice): Promise<readonly Figure[]> {
  const stage = new StyleStage(device, SIZE);
  const bitmap = await loadScene(SIZE.width, SIZE.height);
  stage.uploadImage(bitmap);
  bitmap.close();

  const out: Figure[] = [];
  for (const sheet of SHEETS) {
    const tiles: Uint8Array[] = [];
    for (const shot of sheet.shots) {
      const controls: StyleControls = { ...defaultControls(shot.style), ...shot.controls };
      await stage.render(shot.style, controls, 'full', true);
      tiles.push(halve(await stage.readOutput(), SIZE.width, SIZE.height));
    }

    const laid = tile(tiles, SIZE.width >> 1, SIZE.height >> 1, sheet.columns);
    out.push({
      name: sheet.name,
      width: laid.width,
      height: laid.height,
      columns: sheet.columns,
      tiles: sheet.shots.map((shot) => shot.label),
      rgb: toBase64(laid.rgb),
    });
  }

  stage.dispose();
  return out;
}
